/* From Uiverse.io by pamtbi - Tags: button, minecraft */
.__UIV_SCOPE__ .button {
  display: grid;
  grid-template-columns: repeat(6, 1fr);
  grid-template-rows: repeat(4, 1fr);
  width: 70px;
  aspect-ratio: 3 / 2;
  border: none;
  border-radius: 0px;
  margin: 0 auto;
  padding: 0;
  box-shadow: 0px 5px 0px 0px rgb(102,102,102);
  transition: all .15s;
  position: relative;
  padding: 0
}

.__UIV_SCOPE__ .button:hover {
  transform: translateY(-1px);
}

.__UIV_SCOPE__ .button:active {
  box-shadow: none;
  transform: translateY(5px);
}

.__UIV_SCOPE__ .button__bg {
  height: 100%;
  aspect-ratio: 1 / 1;
  align-self: stretch;
}

.__UIV_SCOPE__ .button__bg-1, .__UIV_SCOPE__ .button__bg-7, .__UIV_SCOPE__ .button__bg-13, .__UIV_SCOPE__ .button__bg-20, .__UIV_SCOPE__ .button__bg-19, .__UIV_SCOPE__ .button__bg-8, .__UIV_SCOPE__ .button__bg-9, .__UIV_SCOPE__ .button__bg-10, .__UIV_SCOPE__ .button__bg-12 {
  background: #494949;
}

.__UIV_SCOPE__ .button__bg-6, .__UIV_SCOPE__ .button__bg-4, .__UIV_SCOPE__ .button__bg-5, .__UIV_SCOPE__ .button__bg-14, .__UIV_SCOPE__ .button__bg-15, .__UIV_SCOPE__ .button__bg-16, .__UIV_SCOPE__ .button__bg-21 {
  background: #505050;
}

.__UIV_SCOPE__ .button__bg-2, .__UIV_SCOPE__ .button__bg-3, .__UIV_SCOPE__ .button__bg-18, .__UIV_SCOPE__ .button__bg-17 {
  background: #5a5a5a;
}

.__UIV_SCOPE__ .button__bg-11, .__UIV_SCOPE__ .button__bg-22 {
  background: #414141;
}

.__UIV_SCOPE__ .button__bg-23, .__UIV_SCOPE__ .button__bg-24 {
  background: #535353;
}

.__UIV_SCOPE__ .span {
  position: absolute;
  top: 50%;
  left: 50%;
  transform: translate(-50%, -50%);
  font-size: 9px;
  width: 100%;
  color: rgb(223, 217, 189);
  display: block;
  text-shadow: 0 0 5px #FFF, 0 0 10px #FFF, 0 0 15px #FFF, 0 0 20px #49ff18, 0 0 30px #49FF18, 0 0 40px #49FF18, 0 0 55px #49FF18, 0 0 75px #49ff18;
}
